function t(key,vars={}){const value=(LANGUAGES[language]||LANGUAGES.en)[key]??EXTRA_I18N[language]?.[key]??LANGUAGES.en[key]??EXTRA_I18N.en[key]??key;return value.replace(/\{(\w+)\}/g,(_,name)=>vars[name]??'')}
const METRIC_I18N={nominal:'nominalGDP',real:'realGDP',nominalPerCapita:'nominalPerCapita',realPerCapita:'realPerCapita'};
function applyLanguage(){const lang=language;document.documentElement.lang=lang==='zh-Hans'?'zh-CN':lang==='zh-Hant'?'zh-TW':lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=`Macro 365 | ${t('footerTitle')}`;renderApp();if(gdpRows.length)populateCountrySelect();switchPage(currentPage,false);renderBars();renderInflation();if(countryHistory.length)renderCountryHistory(countryHistory,$('country-indicator').value);updateClock();}
function translateCountryOptions(){const select=$('country-select');const names=new Intl.DisplayNames([language],{type:'region'});for(const row of gdpRows){const option=select.querySelector(`option[value="${row.code}"]`);if(option){const region=row.code==='USA'?'US':row.code==='CHN'?'CN':row.code==='KOR'?'KR':row.code==='RUS'?'RU':row.code==='TUR'?'TR':row.code==='VNM'?'VN':row.code==='IRN'?'IR':row.code==='EGY'?'EG':row.code==='SAU'?'SA':row.code==='ARE'?'AE':row.code==='HKG'?'HK':row.code==='TWN'?'TW':row.code;option.textContent=names.of(region)||row.name}}}
function countryDisplayName(row){try{const region=row.code==='USA'?'US':row.code==='CHN'?'CN':row.code==='KOR'?'KR':row.code==='RUS'?'RU':row.code==='TUR'?'TR':row.code==='VNM'?'VN':row.code==='IRN'?'IR':row.code==='EGY'?'EG':row.code==='SAU'?'SA':row.code==='ARE'?'AE':row.code==='HKG'?'HK':row.code==='TWN'?'TW':row.code;return new Intl.DisplayNames([language],{type:'region'}).of(region)||row.name}catch{return row.name}}
function populateCountrySelect(){const select=$('country-select'),preferredCode=select.value||selectedCountryCode;select.innerHTML=gdpRows.slice().sort((a,b)=>countryDisplayName(a).localeCompare(countryDisplayName(b),language)).map(row=>`<option value="${esc(row.code)}">${esc(countryDisplayName(row))}</option>`).join('');const nextCode=gdpRows.some(row=>row.code===preferredCode)?preferredCode:gdpRows.some(row=>row.code==='USA')?'USA':gdpRows[0]?.code;if(nextCode){select.value=nextCode;selectedCountryCode=nextCode}}
function setLanguage(next){selectedCountryCode=$('country-select')?.value||selectedCountryCode;language=LANGUAGES[next]?next:'en';localStorage.setItem('macro365-language',language);applyLanguage()}
function refreshLanguageLabels(){const langKey=language==='zh-Hans'?'zhHans':language==='zh-Hant'?'zhHant':language;for(const option of $('language-select').options){const key=`label${langKey[0].toUpperCase()}${langKey.slice(1)}`;option.textContent=option.dataset[key]||option.dataset.labelEn}}
function renderApp(){const app=$('app');if(!app)return;app.innerHTML=`<header class="topbar"><a class="brand" href="#overview" aria-label="Macro 365"><span class="brand-mark">M</span><span>MACRO<span class="brand-light">365</span></span></a><nav class="main-nav" aria-label="${t('navigation')}"><button class="nav-item active" data-page="overview">${t('navOverview')}</button><button class="nav-item" data-page="countries">${t('navCountries')}</button><button class="nav-item" data-page="united-states">${t('navUS')}</button></nav><div class="topbar-right"><span class="market-status"><i></i>${t('serviceStatus')}</span><button class="icon-button" id="refresh-button" title="${t('refresh')}" aria-label="${t('refresh')}">↻</button><button class="api-settings-button" id="api-settings-button" type="button" title="${t('apiSettings')}" aria-label="${t('apiSettings')}">API</button><label class="language-control"><span class="language-icon" aria-hidden="true">文</span><select id="language-select" aria-label="${t('language')}"></select></label></div><section class="api-popover hidden" id="api-popover" role="dialog" aria-labelledby="api-popover-title"><div class="api-popover-head"><h2 id="api-popover-title">${t('apiSettings')}</h2><button class="api-popover-close" id="fred-key-close" type="button" aria-label="${t('apiSettings')}">×</button></div><form id="fred-key-form"><label class="api-key-label" for="fred-key-input">${t('fredApiKey')}</label><input id="fred-key-input" type="password" inputmode="text" autocomplete="new-password" autocapitalize="none" spellcheck="false" placeholder="${FRED_KEY_MASK}" aria-describedby="fred-key-status fred-key-guide fred-key-privacy"><div class="api-key-status" id="fred-key-status"></div><p class="api-key-guide" id="fred-key-guide">${t('fredRegisterGuide')} <a href="https://fredaccount.stlouisfed.org/login/secure/" target="_blank" rel="noopener noreferrer">FRED API key registration</a>.</p><p class="api-key-privacy" id="fred-key-privacy">${t('fredKeyPrivacy')}</p><div class="api-popover-actions"><button class="api-save-button" type="submit">${t('saveKey')}</button><button class="api-clear-button" id="fred-key-clear" type="button">${t('clearKey')}</button></div></form></section></header><main class="shell"><section class="page-heading"><div><div class="eyebrow"><span class="eyebrow-rule"></span> MACROECONOMIC INTELLIGENCE</div><h1 id="page-title">${t(PAGE_KEYS[currentPage][0])}</h1><p id="page-description">${t(PAGE_KEYS[currentPage][1])}</p></div><div class="updated"><span class="status-dot"></span><span id="updated-label"></span></div></section><section class="metric-strip" aria-label="${t('globalIndicators')}">${metricCard('globalGDP','global-gdp','latestYear','global-gdp-year','spark')}${metricCard('globalInflationMedian','global-inflation','countrySample','inflation-sample','spark spark-coral')}${metricCard('economiesCovered','country-count','gdpAvailable','globalScope','bars')}${metricCard('macroClock','clock-value','tokyoTime','date-value','clock')}</section><section class="content-grid"><article class="panel chart-panel"><div class="panel-heading"><div><div class="section-kicker">GLOBAL GDP</div><h2>${t('globalGdpRanking')}</h2><p>${t('rankingSubtitle')}</p></div><button class="icon-button subtle" id="sort-button" title="${t('sort')}" aria-label="${t('sort')}">↓</button></div><div class="metric-tabs" role="tablist" aria-label="${t('gdpMetrics')}">${metricTab('nominal')}${metricTab('real')}${metricTab('nominalPerCapita')}${metricTab('realPerCapita')}</div><div class="chart-summary"><div><span class="summary-label">${t('selectedMetric')}</span><strong id="chart-caption"></strong></div><span id="chart-year" class="data-year"></span></div><div id="bar-chart" class="bar-chart" aria-live="polite"></div><div class="chart-footer"><span><i class="legend-dot"></i> <span id="chart-legend"></span></span><span>${t('sourceWorldBank')}</span></div></article><article class="panel inflation-panel"><div class="panel-heading"><div><div class="section-kicker">PRICE PRESSURES</div><h2>${t('globalInflationRanking')}</h2><p>${t('latestInflation')}</p></div><span class="pill">CPI YoY</span></div><div class="chart-summary"><div><span class="summary-label">${t('selectedMetric')}</span><strong>${t('inflationRate')}</strong></div><span id="inflation-year" class="data-year"></span></div><div id="inflation-list" class="inflation-list" aria-live="polite"></div><div class="chart-footer"><span><i class="inflation-legend-dot"></i>${t('inflationRate')}</span><span>${t('sourceWorldBank')}</span></div></article></section><section id="countries-page" class="secondary-page hidden"><article class="panel country-page-panel"><div class="panel-heading"><div><div class="section-kicker">COUNTRY ANALYTICS</div><h2>${t('countryMacroData')}</h2><p>${t('countryDataSubtitle')}</p></div><div class="panel-actions"><label class="select-wrap"><span class="sr-only">${t('selectCountry')}</span><select id="country-select"></select></label><label class="select-wrap"><span class="sr-only">${t('selectMetric')}</span><select id="country-indicator"><option value="gdp">${t('nominalGDP')}</option><option value="inflation">${t('inflationRate')}</option><option value="cpi">CPI</option></select></label></div></div><div class="history-summary" id="country-summary"></div><div id="history-chart" class="history-chart"></div><div class="table-scroll"><table><thead><tr><th>${t('year')}</th><th id="history-metric-heading"></th><th>${t('yearOverYear')}</th></tr></thead><tbody id="history-table"></tbody></table></div></article></section><section id="us-page" class="secondary-page hidden"><div class="us-page-heading"><div><div class="section-kicker">UNITED STATES · FRED</div><h2>${t('usMacroData')}</h2><p>${t('usMacroSubtitle')}</p></div><div class="key-state"><span class="key-indicator" id="fred-key-indicator"></span><span id="fred-key-state">${fredKeyStatusLabel()}</span></div></div><div class="us-tabs" role="tablist">${usTab('growth','growthPrices',true)}${usTab('rates','ratesTreasuries')}${usTab('labor','laborMarket')}</div><div id="us-series" class="us-series-grid"></div><article class="api-guide panel"><div class="api-guide-icon">API</div><div><h3>${t('apiSettings')}</h3><p>${t('fredKeyPrivacy')}</p></div><span class="api-guide-badge">${t('fredDefaultActive')}</span></article></section><footer class="footer"><span>MACRO365 <span class="footer-divider">/</span> ${t('footerTitle')}</span><span>${t('dataSources')}: World Bank · FRED</span></footer></main>`;renderLanguageOptions();bindEvents();renderUsCards(document.querySelector('.us-tab.active')?.dataset.usTab||activeUsTab);if(currentPage==='united-states')renderFredKeyGuide()}
function metricCard(title,value,foot,valueId,decoration){const isGlobalGDP=title==='globalGDP';const content=decoration==='spark'&&!isGlobalGDP?`<svg class="spark" viewBox="0 0 140 34" aria-hidden="true"><path d="M1 27 C18 25 23 18 36 21 S53 24 67 15 S89 20 101 11 S122 13 139 3"/></svg>`:decoration==='bars'?'<div class="mini-bars" aria-hidden="true">'+Array.from({length:12},()=>'<i></i>').join('')+'</div>':decoration==='spark'?'':'<div class="calendar-icon">◷</div>';return `<article class="metric-card"><div class="metric-label">${t(isGlobalGDP?'globalNominalGDP':title)} <span>${title==='macroClock'?'MARKET CLOCK':'WORLD BANK'}</span></div><div class="metric-value" id="${value}">—</div>${isGlobalGDP?`<div class="metric-unit-note">${t('gdpMagnitudeNote')}</div>`:''}<div class="metric-foot"><span class="muted">${t(foot)}</span><b id="${valueId}">${valueId==='global-gdp-year'||valueId==='inflation-sample'?'—':''}</b></div>${content}</article>`}
function metricTab(metric){const active=metric===selectedMetric;return `<button class="metric-tab${active?' active':''}" role="tab" aria-selected="${active}" data-metric="${metric}">${t(METRIC_I18N[metric])}</button>`}
function usTab(id,label,active=false){return `<button class="us-tab${active?' active':''}" data-us-tab="${id}">${t(label)}</button>`}
function renderLanguageOptions(){const select=$('language-select');select.innerHTML=LANGUAGE_OPTIONS.map(([code,name])=>`<option value="${code}">${name}</option>`).join('');select.value=language}
function bindEvents(){document.querySelectorAll('[data-page]').forEach(button=>button.addEventListener('click',()=>switchPage(button.dataset.page)));document.querySelectorAll('.metric-tab').forEach(button=>button.addEventListener('click',()=>{selectedMetric=button.dataset.metric;document.querySelectorAll('.metric-tab').forEach(tab=>{const active=tab===button;tab.classList.toggle('active',active);tab.setAttribute('aria-selected',String(active))});loadRankingMetric()}));$('sort-button').addEventListener('click',()=>{sortDescending=!sortDescending;$('sort-button').textContent=sortDescending?'↓':'↑';renderBars()});$('refresh-button').addEventListener('click',()=>{loadOverview(true);if(currentPage==='united-states')loadFredTab(activeUsTab,true);showToast(t('refreshing'))});$('country-select').addEventListener('change',()=>{selectedCountryCode=$('country-select').value;loadCountryHistory()});$('country-indicator').addEventListener('change',loadCountryHistory);$('language-select').addEventListener('change',event=>setLanguage(event.target.value));document.querySelectorAll('.us-tab').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.us-tab').forEach(tab=>tab.classList.toggle('active',tab===button));renderUsCards(button.dataset.usTab)}));$('api-settings-button').addEventListener('click',openApiSettings);$('fred-key-close').addEventListener('click',closeApiSettings);$('fred-key-form').addEventListener('submit',saveFredKey);$('fred-key-clear').addEventListener('click',clearFredKey);document.addEventListener('keydown',event=>{if(event.key==='Escape')closeApiSettings()});document.addEventListener('click',event=>{const popover=$('api-popover');if(!popover.classList.contains('hidden')&&!popover.contains(event.target)&&!$('api-settings-button').contains(event.target))closeApiSettings()});}
function refreshLocalizedViews(){if(countryHistory.length)loadCountryHistory()}
const fmt=(value,digits=1)=>new Intl.NumberFormat('en-US',{maximumFractionDigits:digits}).format(value);
const fmtFixed=(value,digits=2)=>new Intl.NumberFormat('en-US',{minimumFractionDigits:digits,maximumFractionDigits:digits}).format(value);
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function apiUrl(path){return `${API}/${path}${path.includes('?')?'&':'?'}format=json&per_page=20000`}
function saveApiCache(key,record){const serialized=JSON.stringify(record);try{localStorage.setItem(key,serialized);return}catch{}const entries=[];try{for(let index=0;index<localStorage.length;index++){const candidate=localStorage.key(index);if(candidate?.startsWith(API_CACHE_PREFIX)&&candidate!==key){let expiresAt=0;try{expiresAt=JSON.parse(localStorage.getItem(candidate)||'{}').expiresAt||0}catch{}entries.push({key:candidate,expiresAt})}}}catch{return}entries.sort((a,b)=>a.expiresAt-b.expiresAt);for(const entry of entries){try{localStorage.removeItem(entry.key);localStorage.setItem(key,serialized);return}catch{}}}
async function wb(path,{force=false}={}){const url=apiUrl(path),cacheKey=API_CACHE_PREFIX+url,now=Date.now();let cached=null;try{cached=JSON.parse(localStorage.getItem(cacheKey)||'null')}catch{}if(!force&&cached?.expiresAt>now)return cached.data;if(apiInFlight.has(url))return apiInFlight.get(url);const request=(async()=>{try{const response=await fetch(url);if(!response.ok)throw new Error(`World Bank ${response.status}`);const json=await response.json();if(!Array.isArray(json)||!Array.isArray(json[1]))throw new Error('数据源暂不可用');const record={expiresAt:Date.now()+API_CACHE_TTL,data:json[1]};saveApiCache(cacheKey,record);return record.data}catch(error){if(cached?.data)return cached.data;throw error}})();apiInFlight.set(url,request);try{return await request}finally{apiInFlight.delete(url)}}
function countriesOnly(rows){return rows.filter(row=>row.countryiso3code&&!EXCLUDED.has(row.countryiso3code)&&row.countryiso3code.length===3&&row.value!==null)}
function latestCommonYear(rows){const year=rows.reduce((latest,row)=>Math.max(latest,Number(row.date)||0),0);return{year:year||'—',rows:year?rows.filter(row=>Number(row.date)===year):[]}}
function countryFlag(row){if(FLAGS[row.code])return FLAGS[row.code];const iso2=row.iso2?.toUpperCase();return iso2&&/^[A-Z]{2}$/.test(iso2)?[...iso2].map(char=>String.fromCodePoint(127397+char.charCodeAt(0))).join(''):'🏳️'}
function formatMoney(value){const billions=value/1e9;if(Math.abs(billions)>=1000)return `$${fmtFixed(billions/1000)}T`;return `$${fmtFixed(billions)}B`}
function localeNumber(value,digits=1){const locale=language==='zh-Hans'?'zh-CN':language==='zh-Hant'?'zh-TW':language;return new Intl.NumberFormat(locale,{maximumFractionDigits:digits}).format(value)}
function localeFixed(value,digits=2){const locale=language==='zh-Hans'?'zh-CN':language==='zh-Hant'?'zh-TW':language;return new Intl.NumberFormat(locale,{minimumFractionDigits:digits,maximumFractionDigits:digits}).format(value)}
function displayValue(value,metric){if(metric.includes('PerCapita'))return `$${fmtFixed(value)} /人`;return formatMoney(value)}
function setUpdated(label){$('updated-label').textContent=label}
function showToast(message){const el=$('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2600)}
function renderBars(){const metric=selectedMetric,meta=METRICS[metric];let rows=[...gdpRows];rows.sort((a,b)=>(sortDescending?-1:1)*(a.value-b.value));$('chart-caption').textContent=`${t(METRIC_I18N[metric])} · ${meta.unit}`;$('chart-year').textContent=`${t('dataYear')} ${gdpYear}`;$('chart-legend').textContent=metric.includes('PerCapita')?`${t(METRIC_I18N[metric])} (USD per capita)`:`${t(METRIC_I18N[metric])} (USD billions)`;const max=Math.max(1,...rows.map(row=>row.value));$('bar-chart').innerHTML=rows.map((row,index)=>`<div class="bar-row"><span class="bar-rank">${index+1}</span><span class="bar-country" title="${esc(row.code)}"><span class="bar-country-name">${esc(countryDisplayName(row))}</span><span class="flag" aria-hidden="true">${countryFlag(row)}</span></span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(1,row.value/max*100)}%"></div></div><span class="bar-value">${metric.includes('PerCapita')?'$'+fmtFixed(row.value):formatMoney(row.value)}</span></div>`).join('')||`<div class="empty-cell">${t('indicatorUnavailable')}</div>`;}
async function loadRankingMetric(){const meta=METRICS[selectedMetric];$('chart-caption').textContent=`${t(METRIC_I18N[selectedMetric])} · ${meta.unit}`;$('chart-year').textContent=t('loading');$('bar-chart').innerHTML=`<div class="loading-line">${t('loadingRankings')}</div>`;try{const latest=latestCommonYear(countriesOnly(await wb(`country/all/indicator/${meta.id}?date=1960:2026`)));if(!latest.rows.length)throw new Error(`No observations returned for ${meta.id}`);gdpRows=latest.rows.map(row=>({code:row.countryiso3code,iso2:row.country?.iso2Code||row.country?.id,name:row.country.value,value:row.value,year:row.date}));gdpYear=latest.year;$('country-count').textContent=String(gdpRows.length);populateCountrySelect();renderBars();setUpdated(t('dataUpdated',{time:new Date().toLocaleTimeString(language,{hour:'2-digit',minute:'2-digit'})}))}catch(error){console.error(`Failed to load ${selectedMetric} ranking:`,error);$('chart-year').textContent='';$('bar-chart').innerHTML=`<div class="empty-cell">${t('metricUnavailable')}</div>`}}
function renderInflation(){const rows=[...inflationRows].sort((a,b)=>b.value-a.value),max=Math.max(1,...rows.map(row=>row.value));$('inflation-year').textContent=`${t('dataYear')} ${inflationYear}`;$('inflation-list').innerHTML=rows.map((row,index)=>`<div class="inflation-row"><span class="inflation-rank">${index+1}</span><span class="inflation-country" title="${esc(row.code)}"><span class="inflation-country-name">${esc(countryDisplayName(row))}</span><span class="flag" aria-hidden="true">${countryFlag(row)}</span></span><div class="inflation-track"><div class="inflation-fill" style="width:${Math.max(2,Math.max(0,row.value)/max*100)}%"></div></div><span class="inflation-value">${localeFixed(row.value)}%</span></div>`).join('')||`<div class="empty-cell">${t('indicatorUnavailable')}</div>`}
async function loadOverview(forceRefresh=false){setUpdated(language==='en'?'Connecting to data sources':t('loading'));try{const metric=METRICS.nominal.id;const [gdp,cpi]=await Promise.all([wb(`country/all/indicator/${metric}?date=1960:2026`,{force:forceRefresh}),wb('country/all/indicator/FP.CPI.TOTL.ZG?date=1960:2026',{force:forceRefresh})]);const latestGDP=latestCommonYear(countriesOnly(gdp)),latestCPI=latestCommonYear(countriesOnly(cpi));gdpRows=latestGDP.rows.map(row=>({code:row.countryiso3code,iso2:row.country?.iso2Code||row.country?.id,name:row.country.value,value:row.value,year:row.date}));gdpYear=latestGDP.year;inflationYear=latestCPI.year;inflationRows=latestCPI.rows.map(row=>({code:row.countryiso3code,iso2:row.country?.iso2Code||row.country?.id,name:row.country.value,value:row.value,year:row.date}));const total=gdpRows.reduce((sum,row)=>sum+row.value,0);$('global-gdp').textContent=total?formatMoney(total):'—';$('global-gdp-year').textContent=gdpYear;$('country-count').textContent=String(gdpRows.length);const sortedCPI=inflationRows.map(row=>row.value).sort((a,b)=>a-b);const median=sortedCPI.length?sortedCPI[Math.floor(sortedCPI.length/2)]:null;$('global-inflation').textContent=median===null?'—':`${localeFixed(median)}%`;$('inflation-sample').textContent=t('inflationSampleCount',{count:inflationRows.length});renderBars();renderInflation();setUpdated(t('dataUpdated',{time:new Date().toLocaleTimeString(language,{hour:'2-digit',minute:'2-digit'})}));populateCountrySelect();if(!$('country-select').value)$('country-select').value=gdpRows.some(row=>row.code==='USA')?'USA':gdpRows[0]?.code||'';loadCountryHistory()}catch(error){console.error(error);setUpdated(t('dataSourceError'));$('bar-chart').innerHTML=`<div class="empty-cell">${t('indicatorUnavailable')}</div>`;$('inflation-list').innerHTML=`<div class="empty-cell">${t('indicatorUnavailable')}</div>`}}
const SERIES_LABELS={GDP:{en:'Gross Domestic Product',zhHans:'国内生产总值',zhHant:'國內生產總值',ja:'国内総生産',ko:'국내총생산',es:'Producto interior bruto',it:'Prodotto interno lordo',ar:'الناتج المحلي الإجمالي'},CORESTICKM159SFRBATL:{en:'Sticky Core CPI',zhHans:'核心黏性 CPI',zhHant:'核心黏性 CPI',ja:'粘着性コア CPI',ko:'핵심 경직 CPI',es:'IPC subyacente persistente',it:'CPI core persistente',ar:'مؤشر الأسعار الأساسي'},CPIAUCSL:{en:'Consumer Price Index',zhHans:'消费者价格指数',zhHant:'消費者物價指數',ja:'消費者物価指数',ko:'소비자물가지수',es:'Índice de precios al consumidor',it:'Indice dei prezzi al consumo',ar:'مؤشر أسعار المستهلك'},M2SL:{en:'M2 Money Supply (Monthly)',zhHans:'M2 货币供应量（月度）',zhHant:'M2 貨幣供給量（月）',ja:'M2マネーサプライ（月次）',ko:'M2 통화공급량 (월간)',es:'Oferta monetaria M2 (mensual)',it:'Offerta di moneta M2 (mensile)',ar:'عرض النقود M2 (شهري)'},WM2NS:{en:'M2 Money Supply (Weekly)',zhHans:'M2 货币供应量（周度）',zhHant:'M2 貨幣供給量（週）',ja:'M2マネーサプライ（週次）',ko:'M2 통화공급량 (주간)',es:'Oferta monetaria M2 (semanal)',it:'Offerta di moneta M2 (settimanale)',ar:'عرض النقود M2 (أسبوعي)'},FEDFUNDS:{en:'Federal Funds Rate',zhHans:'联邦基金利率',zhHant:'聯邦資金利率',ja:'フェデラルファンド金利',ko:'연방기금금리',es:'Tasa de fondos federales',it:'Tasso sui fondi federali',ar:'سعر الأموال الفيدرالية'},DTB1YR:{en:'1-Year Treasury Yield',zhHans:'1 年期国债收益率',zhHant:'1 年期公債殖利率',ja:'1年米国債利回り',ko:'1년 국채 수익률',es:'Rendimiento del Tesoro a 1 año',it:'Rendimento Treasury a 1 anno',ar:'عائد سندات الخزانة لعام واحد'},DGS5:{en:'5-Year Treasury Yield',zhHans:'5 年期国债收益率',zhHant:'5 年期公債殖利率',ja:'5年米国債利回り',ko:'5년 국채 수익률',es:'Rendimiento del Tesoro a 5 años',it:'Rendimento Treasury a 5 anni',ar:'عائد سندات الخزانة لخمس سنوات'},DGS10:{en:'10-Year Treasury Yield',zhHans:'10 年期国债收益率',zhHant:'10 年期公債殖利率',ja:'10年米国債利回り',ko:'10년 국채 수익률',es:'Rendimiento del Tesoro a 10 años',it:'Rendimento Treasury a 10 anni',ar:'عائد سندات الخزانة لعشر سنوات'},T10Y2Y:{en:'10-Year - 2-Year Spread',zhHans:'10 年 - 2 年利差',zhHant:'10 年 - 2 年利差',ja:'10年 - 2年スプレッド',ko:'10년 - 2년 스프레드',es:'Diferencial 10 años - 2 años',it:'Differenziale 10 anni - 2 anni',ar:'فارق 10 سنوات - سنتين'},UNEMPLOY:{en:'Unemployment Level',zhHans:'失业人数',zhHant:'失業人數',ja:'失業者数',ko:'실업자 수',es:'Nivel de desempleo',it:'Livello di disoccupazione',ar:'مستوى البطالة'},UNRATE:{en:'Unemployment Rate',zhHans:'失业率',zhHant:'失業率',ja:'失業率',ko:'실업률',es:'Tasa de desempleo',it:'Tasso di disoccupazione',ar:'معدل البطالة'},PAYEMS:{en:'Nonfarm Payrolls',zhHans:'非农就业人数',zhHant:'非農就業人數',ja:'非農業部門雇用者数',ko:'비농업 고용자 수',es:'Nóminas no agrícolas',it:'Occupazione non agricola',ar:'التوظيف في القطاعات غير الزراعية'}};
function seriesLabel(id){return SERIES_LABELS[id]?.[language]||SERIES_LABELS[id]?.en||id}
function seriesFrequency(text){if(language==='en')return text;if(language==='zh-Hans')return text.replace('季度','季度').replace('月度','月度').replace('周度','周度').replace('日度','日度').replace('十亿美元','十亿美元');if(language==='zh-Hant')return text.replaceAll('月度','月').replaceAll('周度','週').replaceAll('日度','日').replaceAll('十亿美元','十億美元');if(language==='ja')return text.replaceAll('季度','四半期').replaceAll('月度','月次').replaceAll('周度','週次').replaceAll('日度','日次').replaceAll('十亿美元','10億ドル');if(language==='ko')return text.replaceAll('季度','분기').replaceAll('月度','월간').replaceAll('周度','주간').replaceAll('日度','일간').replaceAll('十亿美元','십억 달러');if(language==='es')return text.replaceAll('季度','Trimestral').replaceAll('月度','Mensual').replaceAll('周度','Semanal').replaceAll('日度','Diario').replaceAll('十亿美元','miles de millones de USD');if(language==='it')return text.replaceAll('季度','Trimestrale').replaceAll('月度','Mensile').replaceAll('周度','Settimanale').replaceAll('日度','Giornaliero').replaceAll('十亿美元','miliardi USD');return text.replaceAll('季度','ربع سنوي').replaceAll('月度','شهري').replaceAll('周度','أسبوعي').replaceAll('日度','يومي').replaceAll('十亿美元','مليار دولار')}
function getFredApiKey(){return localStorage.getItem(FRED_KEY_STORAGE)?.trim()||FRED_DEFAULT_API_KEY}
function fredKeyStatusLabel(){return localStorage.getItem(FRED_KEY_STORAGE)?.trim()?t('keySavedLocally'):t('fredDefaultActive')}
function openApiSettings(){const popover=$('api-popover');popover.classList.remove('hidden');$('fred-key-input').value='';$('fred-key-input').placeholder=FRED_KEY_MASK;$('fred-key-status').textContent=fredKeyStatusLabel();$('fred-key-input').focus()}
function closeApiSettings(){$('api-popover')?.classList.add('hidden')}
function clearFredCache(){try{for(let index=localStorage.length-1;index>=0;index--){const key=localStorage.key(index);if(key?.startsWith(FRED_CACHE_PREFIX))localStorage.removeItem(key)}}catch{}}
function refreshFredViews(){const label=$('fred-key-state');if(label)label.textContent=fredKeyStatusLabel();if(currentPage==='united-states')loadFredTab(activeUsTab,true)}
function saveFredKey(event){event.preventDefault();const key=$('fred-key-input').value.trim();if(!/^[a-z0-9]{32}$/.test(key)){$('fred-key-status').textContent=t('keyFormatError');$('fred-key-input').focus();return}try{localStorage.setItem(FRED_KEY_STORAGE,key)}catch{$('fred-key-status').textContent=t('fredLoadError');return}clearFredCache();$('fred-key-input').value='';$('fred-key-status').textContent=t('keySaved');refreshFredViews();showToast(t('keySaved'))}
function clearFredKey(){try{localStorage.removeItem(FRED_KEY_STORAGE)}catch{$('fred-key-status').textContent=t('fredLoadError');return}clearFredCache();$('fred-key-input').value='';$('fred-key-status').textContent=t('keyCleared');refreshFredViews();showToast(t('keyCleared'))}
function renderUsCards(tab='growth'){activeUsTab=SERIES[tab]?tab:'growth';const cards=SERIES[activeUsTab];$('us-series').innerHTML=cards.map(([label,id,short,frequency])=>`<article class="series-card" data-series="${id}"><div class="series-card-head"><h3>${seriesLabel(id)}</h3><svg class="series-spark" viewBox="0 0 80 22" aria-hidden="true"><path d="M1 16 C10 14 12 6 21 10 S32 15 42 8 S54 13 62 6 S72 8 79 2"/></svg></div><div class="series-value series-value-placeholder">${t('fredLoading')}</div><div class="series-foot"><span>${id} · ${seriesFrequency(frequency)}</span><span>${t('fredLoading')}</span></div></article>`).join('');loadFredTab(activeUsTab)}
function loadFredTab(tab,force=false){if(currentPage!=='united-states')return;const cards=SERIES[tab]||[];Promise.allSettled(cards.map(([,seriesId])=>loadFredSeries(seriesId,force))).then(results=>{results.forEach((result,index)=>{const seriesId=cards[index][1];if(result.status==='fulfilled')renderFredCard(seriesId,result.value);else renderFredError(seriesId)})})}
async function loadFredSeries(seriesId,force=false){const apiKey=getFredApiKey(),requestKey=`${seriesId}:${apiKey}`,cacheKey=FRED_CACHE_PREFIX+seriesId;let cached=null;try{cached=JSON.parse(localStorage.getItem(cacheKey)||'null')}catch{}if(!force&&cached?.expiresAt>Date.now())return cached.data;if(fredInFlight.has(requestKey))return fredInFlight.get(requestKey);const request=(async()=>{const response=await fetch(`/api/fred/series/observations?series_id=${encodeURIComponent(seriesId)}`,{headers:{'X-FRED-API-Key':apiKey}});const payload=await response.json();if(!response.ok||payload.error_code||!Array.isArray(payload.observations))throw new Error('FRED request failed');const latest=payload.observations.find(row=>row.value!=='.'&&Number.isFinite(Number(row.value)));if(!latest)throw new Error('No observation');const data={date:latest.date,value:Number(latest.value)};if(getFredApiKey()===apiKey){try{localStorage.setItem(cacheKey,JSON.stringify({expiresAt:Date.now()+FRED_CACHE_TTL,data}))}catch{}}return data})();fredInFlight.set(requestKey,request);try{return await request}finally{fredInFlight.delete(requestKey)}}
function formatFredValue(seriesId,value){if(['GDP','M2SL','WM2NS'].includes(seriesId))return value>=1000?`$${localeFixed(value/1000)}T`:`$${localeFixed(value)}B`;if(['PAYEMS','UNEMPLOY'].includes(seriesId))return value>=1000?`${localeFixed(value/1000)}M`:`${localeFixed(value)}K`;if(['CORESTICKM159SFRBATL','FEDFUNDS','DTB1YR','DGS5','DGS10','T10Y2Y','UNRATE'].includes(seriesId))return `${localeFixed(value)}%`;return localeFixed(value)}
function renderFredCard(seriesId,data){const card=document.querySelector(`[data-series="${seriesId}"]`);if(!card)return;card.querySelector('.series-value').textContent=formatFredValue(seriesId,data.value);card.querySelector('.series-value').classList.remove('series-value-placeholder');card.querySelector('.series-foot span:last-child').textContent=t('fredLatest',{date:data.date})}
function renderFredError(seriesId){const card=document.querySelector(`[data-series="${seriesId}"]`);if(!card)return;card.querySelector('.series-value').textContent='—';card.querySelector('.series-foot span:last-child').textContent=t('fredLoadError')}
function renderFredKeyGuide(){}
function updateClock(){const now=new Date();$('clock-value').textContent=new Intl.DateTimeFormat(language,{timeZone:'Asia/Tokyo',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(now);$('date-value').textContent=new Intl.DateTimeFormat(language,{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(now)}
function switchPage(page,scroll=true){if(!PAGE_KEYS[page])return;currentPage=page;document.querySelectorAll('.nav-item').forEach(button=>button.classList.toggle('active',button.dataset.page===page));$('countries-page').classList.toggle('hidden',page!=='countries');$('us-page').classList.toggle('hidden',page!=='united-states');document.querySelector('.content-grid').classList.toggle('hidden',page!=='overview');$('page-title').textContent=t(PAGE_KEYS[page][0]);$('page-description').textContent=t(PAGE_KEYS[page][1]);if(scroll)window.scrollTo({top:0,behavior:'smooth'});if(page==='countries')loadCountryHistory();if(page==='united-states'){renderFredKeyGuide();renderUsCards(activeUsTab)}}
async function loadCountryHistory(){if(!gdpRows.length)return;const code=$('country-select').value||'USA',indicator=$('country-indicator').value,metric=indicator==='gdp'?'NY.GDP.MKTP.CD':indicator==='inflation'?'FP.CPI.TOTL.ZG':'FP.CPI.TOTL';$('history-chart').innerHTML=`<div class="loading-line">${t('historyLoading')}</div>`;try{const data=(await wb(`country/${encodeURIComponent(code)}/indicator/${metric}?date=1960:2026`)).filter(row=>row.value!==null).map(row=>({year:Number(row.date),value:row.value})).sort((a,b)=>a.year-b.year);countryHistory=data;renderCountryHistory(data,indicator,code)}catch(error){$('history-chart').innerHTML=`<div class="empty-cell">${t('historyUnavailable')}</div>`;console.error(error)}}
function renderCountryHistory(data,indicator,code=$('country-select').value||'USA'){const country=gdpRows.find(row=>row.code===code),last=data.at(-1),change=data.length>1?(last.value/data[data.length-2].value-1)*100:null;$('country-summary').innerHTML=`<div class="history-stat"><span>${t('economy')}</span><strong>${esc(country?countryDisplayName(country):code)}</strong></div><div class="history-stat"><span>${t('latestObservation')} · ${last?.year||'—'}</span><strong>${last?(indicator==='gdp'?formatMoney(last.value):localeNumber(last.value,2)+(indicator==='cpi'?'':'%')):'—'}</strong></div><div class="history-stat"><span>${t('yoyChange')}</span><strong>${change===null?'—':(change>0?'+':'')+localeNumber(change,2)+'%'}</strong></div>`;$('history-metric-heading').textContent=indicator==='gdp'?t('nominalGDP'):indicator==='inflation'?t('inflationRate'):'CPI';renderHistory(data,indicator);$('history-table').innerHTML=data.slice().reverse().map((row,index,all)=>{const prior=all[index+1],delta=prior?row.value/prior.value-1:null;return `<tr><td class="number-cell">${row.year}</td><td class="number-cell">${indicator==='gdp'?formatMoney(row.value):localeNumber(row.value,2)+(indicator==='cpi'?'':'%')}</td><td class="number-cell ${delta>=0?'positive':'negative'}">${delta===null?'—':(delta>0?'+':'')+localeNumber(delta*100,2)+'%'}</td></tr>`}).join('')||`<tr><td colspan="3" class="empty-cell">${t('noHistory')}</td></tr>`}
function renderHistory(data,indicator){if(!data.length){$('history-chart').innerHTML=`<div class="empty-cell">${t('noHistory')}</div>`;return}const width=800,height=215,pad=5,values=data.map(row=>row.value),min=Math.min(...values),max=Math.max(...values),range=max-min||1;const points=data.map((row,index)=>`${pad+index/(Math.max(data.length-1,1))*(width-pad*2)},${height-pad-(row.value-min)/range*(height-pad*2)}`).join(' ');$('history-chart').innerHTML=`<svg class="history-svg" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none"><defs><linearGradient id="area-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#548a79"/><stop offset="1" stop-color="#548a79" stop-opacity="0"/></linearGradient></defs><polygon class="history-area" points="${pad},${height} ${points} ${width-pad},${height}"/><polyline class="history-line" points="${points}"/></svg><div class="history-axis"><span>${data[0].year}</span><span>${data[Math.floor(data.length/2)].year}</span><span>${data.at(-1).year}</span></div>`}
renderApp();switchPage(currentPage,false);updateClock();setInterval(updateClock,1000);loadOverview();
